package pagesearch

import (
	"encoding/json"
	"os"
	"strings"
	"testing"
)

// This fixture is generated by the frozen schema4 Yjs model, not a runtime4
// admission/read fixture. Production runtime matching is a separate gate.
func TestFrozenDocument4ModelTextProjection(t *testing.T) {
	raw, err := os.ReadFile("../../testdata/pages-search-docs4-model.json")
	if err != nil {
		t.Fatal(err)
	}
	var fixture struct {
		Schema  int             `json:"schema_version"`
		Outline []DocumentBlock `json:"outline"`
	}
	if err = json.Unmarshal(raw, &fixture); err != nil {
		t.Fatal(err)
	}
	blocks := make([]BlockHash, len(fixture.Outline))
	for i, block := range fixture.Outline {
		blocks[i] = BlockHash{block.ID, block.Hash}
	}
	hash, err := DocumentHash(blocks)
	if err != nil {
		t.Fatal(err)
	}
	source := SourceTag{"workspace", "page", "document", fixture.Schema, 0, 1, hash}
	projection, err := FromDocument(source, fixture.Outline, blocks)
	if err != nil {
		t.Fatal(err)
	}
	if len(projection.Segments) != 2 || projection.Segments[0].Text != "Linked plaintext inline code" || projection.Segments[1].Text != "Code leaf searchable" {
		t.Fatalf("unexpected plaintext: %+v", projection)
	}
	encoded, _, err := projection.Encode()
	if err != nil {
		t.Fatal(err)
	}
	for _, excluded := range []string{"href-canary", "asset-ref-canary", "alt-canary", strings.Repeat("a", 64)} {
		if strings.Contains(string(encoded), excluded) {
			t.Fatalf("indexed image/link metadata %q", excluded)
		}
	}
	// Even unexpected text on a trusted image outline is never searchable.
	fixture.Outline[2].Text = "image-text-canary"
	projection, err = FromDocument(source, fixture.Outline, blocks)
	if err != nil || len(projection.Segments) != 2 {
		t.Fatalf("image text indexed: %+v %v", projection, err)
	}
	// Images still participate in complete source binding.
	changed := append([]BlockHash(nil), blocks...)
	changed[2].Hash = strings.Repeat("b", 64)
	changedHash, _ := DocumentHash(changed)
	if changedHash == source.Hash {
		t.Fatal("image hash omitted from source binding")
	}
	for _, version := range []int{1, 2, 3, 5} {
		source.Schema = version
		if _, err := FromDocument(source, fixture.Outline, blocks); err == nil {
			t.Fatalf("image admitted in schema %d", version)
		}
	}
	source.Schema = 4
	fixture.Outline[2].Parent = "paragraph"
	if _, err := FromDocument(source, fixture.Outline, blocks); err == nil {
		t.Fatal("nested image admitted")
	}
	fixture.Outline[2].Parent = ""
	child := DocumentBlock{"child", "paragraph", "image", strings.Repeat("c", 64), "hidden child"}
	fixture.Outline = append(fixture.Outline, child)
	blocks = append(blocks, BlockHash{child.ID, child.Hash})
	source.Hash, _ = DocumentHash(blocks)
	if _, err := FromDocument(source, fixture.Outline, blocks); err == nil {
		t.Fatal("image child admitted")
	}
	// An image-only valid document has no text; it is not an unsupported document.
	image := fixture.Outline[2]
	blocks = []BlockHash{{image.ID, image.Hash}}
	source.Hash, _ = DocumentHash(blocks)
	projection, err = FromDocument(source, []DocumentBlock{image}, blocks)
	if err != nil || len(projection.Segments) != 0 {
		t.Fatalf("image-only projection: %+v %v", projection, err)
	}
}
